function grid(name) {
  const rows = S[name].split('\n').filter(r => r.length);
  return rows;
}
function svgFrom(layers, w, h, scale, extra = '') {
  // layers: [{rows, x, y, map}] -> merged horizontal runs
  const px = Array.from({ length: h }, () => Array(w).fill(null));
  for (const L of layers) {
    L.rows.forEach((row, j) => {
      [...row].forEach((ch, i) => {
        if (ch === '.' || ch === ' ') return;
        const X = i + (L.x || 0), Y = j + (L.y || 0);
        if (X < 0 || Y < 0 || X >= w || Y >= h) return;
        px[Y][X] = (L.map && L.map[ch]) || PAL[ch] || ch;
      });
    });
  }
  let rects = '';
  for (let y = 0; y < h; y++) {
    let x = 0;
    while (x < w) {
      const c = px[y][x];
      if (!c) { x++; continue; }
      let x2 = x + 1;
      while (x2 < w && px[y][x2] === c) x2++;
      rects += `<rect x="${x}" y="${y}" width="${x2 - x}" height="1" fill="${c}"/>`;
      x = x2;
    }
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w * scale}" height="${h * scale}" shape-rendering="crispEdges" ${extra}>${rects}</svg>`;
}
function sprite(name, scale = 2, opts = {}) {
  const rows = grid(name);
  const w = Math.max(...rows.map(r => r.length)), h = rows.length;
  const layers = [{ rows, map: opts.map }];
  if (name === 'acolyte') {
    const [h1, h2] = ROBES[opts.robe || 'bone'];
    layers[0].map = { h: h1, H: h2, ...(opts.map || {}) };
    if (opts.prop) layers.push({ rows: grid('p_' + opts.prop), x: 5, y: 9 });
    if (opts.sig) {
      const dark = ['ebony', 'clay', 'slate', 'magenta', 'green'].includes(opts.robe);
      layers.push({ rows: grid('sig_' + opts.sig), x: 6, y: 9, map: { o: opts.sigColor || (dark ? '#f7e7b8' : '#3a2a1f') } });
    }
  }
  return svgFrom(layers, w, h, scale);
}
function hydrate(root = document) {
  root.querySelectorAll('i.px').forEach(el => {
    const d = el.dataset;
    el.innerHTML = sprite(d.s, +(d.z || 2), { robe: d.robe, prop: d.prop, sig: d.sig });
  });
}
// resource glyph helper for text: R('gold', 3) => "3<glyph>"
function R(c, n, z = 2) {
  return `<span class="rz">${n !== undefined ? `<b>${n}</b>` : ''}<i class="px" data-s="${c}" data-z="${z}"></i></span>`;
}
window.PX = { sprite, hydrate, R, S, ROBES };
